package com.jnapanam.sportszone.notification.controller;import com.jnapanam.sportszone.notification.dto.*;import com.jnapanam.sportszone.notification.service.NotificationService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/notifications")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class AdminNotificationController{private final NotificationService service;public AdminNotificationController(NotificationService s){service=s;}@GetMapping("/templates")public List<TemplateResponse>templates(){return service.templates();}@PostMapping("/templates")@ResponseStatus(HttpStatus.CREATED)public TemplateResponse create(@Valid@RequestBody TemplateRequest r){return service.create(r);}@PutMapping("/templates/{id}")public TemplateResponse update(@PathVariable UUID id,@Valid@RequestBody TemplateRequest r){return service.update(id,r);}@PostMapping("/broadcasts")public Map<String,Integer>broadcast(@Valid@RequestBody BroadcastRequest r){return Map.of("queued",service.broadcast(r));}@PostMapping("/dispatch")public Map<String,Integer>dispatch(){return Map.of("sent",service.dispatch());}}
